files.content:
.badge {
  display: inline-flex;
  min-height: 26px;
  align-items: center;
  justify-content: center;
  gap: var(--space-1);
  border: 1px solid var(--border);
  border-radius: var(--radius-pill);
  padding: 0 10px;
  color: var(--foreground);
  background: var(--surface);
  font-size: var(--text-xs);
  font-weight: 500;
  letter-spacing: -0.01em;
  line-height: 1;
  white-space: nowrap;
  user-select: none;
  overflow: clip;
  transition:
    border-color var(--duration-standard) var(--ease-standard),
    background-color var(--duration-standard) var(--ease-standard),
    color var(--duration-standard) var(--ease-standard);
}

.sm {
  min-height: 20px;
  padding: 0 7px;
  font-size: 11px;
}

.md {
  min-height: 26px;
  padding: 0 10px;
  font-size: var(--text-xs);
}

/* Tones - 采用低饱和 Zinc 与克制语义色 */
.neutral {
  background: var(--surface-muted);
  color: var(--foreground);
  border-color: var(--border);
}

.success {
  background: color-mix(in oklch, var(--success) 12%, transparent);
  color: var(--success);
  border-color: color-mix(in oklch, var(--success) 24%, transparent);
}

.info {
  background: color-mix(in oklch, var(--accent) 12%, transparent);
  color: var(--accent);
  border-color: color-mix(in oklch, var(--accent) 24%, transparent);
}

.warning {
  background: color-mix(in oklch, var(--warning) 12%, transparent);
  color: var(--warning);
  border-color: color-mix(in oklch, var(--warning) 24%, transparent);
}

.danger {
  background: color-mix(in oklch, var(--danger) 12%, transparent);
  color: var(--danger);
  border-color: color-mix(in oklch, var(--danger) 24%, transparent);
}

.content {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
}

.iconSlot {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 0.9em;
}
